import math
X=0.0;Y=0.0;PSI=0.0
MEM={}
mode='rev'
fwd_dist=0.0
last_alpha=0.0
L=2.75;H=1.05;LT=2.6

def clip(v,a,b):
    return max(a,min(b,v))

def to_world(x,y):
    c=math.cos(PSI);s=math.sin(PSI)
    return (X+x*c-y*s, Y+x*s+y*c)

def to_veh(wx,wy):
    dx=wx-X;dy=wy-Y;c=math.cos(PSI);s=math.sin(PSI)
    return (dx*c+dy*s, -dx*s+dy*c)

def deq(phi):
    p=math.radians(phi)
    return math.degrees(math.atan(L*math.sin(p)/(LT-H*math.cos(p))))

def gaze_sched(t):
    c=t%3.8
    if c<1.4: return -23.0
    if c<1.9: return 43.0
    if c<3.3: return -23.0
    return -65.0

def control(obs):
    global X,Y,PSI,mode,fwd_dist,last_alpha
    dt=obs.get('dt',0.1) or 0.1
    mo=obs.get('motion',{})
    v=mo.get('v_mps',0.0) or 0.0
    st=obs.get('steer_deg',0.0) or 0.0
    X+=v*math.cos(PSI)*dt;Y+=v*math.sin(PSI)*dt
    PSI+=v*math.tan(math.radians(st))/L*dt
    t=obs.get('t',0.0)
    views=obs.get('views') or {}
    fwd_close=False
    rig=obs.get('rig',{})
    vf=rig.get('vehicle_front',3.6) or 3.6
    vhw=rig.get('vehicle_half_width',0.93) or 0.93
    for name,vw in views.items():
        try:
            o=vw.get('origin',[0,0])
            for wp in vw.get('walls',[]):
                b=wp[0];d=wp[1]
                if name=='periphery' and d>4.5: continue
                x=o[0]+d*math.cos(math.radians(b));y=o[1]+d*math.sin(math.radians(b))
                if x>vf-0.3 and abs(y)<vhw+0.3 and x-vf<0.9: fwd_close=True
                wx,wy=to_world(x,y)
                MEM[(round(wx*5),round(wy*5))]=(wx,wy,t)
        except Exception:
            pass
    if len(MEM)>1500:
        ks=sorted(MEM.keys(),key=lambda k:MEM[k][2])
        for k in ks[:len(MEM)-1200]: del MEM[k]
    phi=obs.get('hitch_deg',0.0) or 0.0
    status=obs.get('status','')
    if mode=='rev' and (abs(phi)>23 or status=='JACKKNIFED'):
        mode='fwd';fwd_dist=0.0
    if mode=='fwd':
        fwd_dist+=max(v,0)*dt
        if (abs(phi)<5 and fwd_dist>1.0) or (fwd_close and fwd_dist>0.2) or fwd_dist>4:
            mode='rev'
        else:
            steer=clip(-1.5*phi,-34,34)
            sp=0.0 if fwd_close else 1.2
            return (steer,sp,0.0)
    R=rig.get('trailer_rear',[-4.55,0]);th=rig.get('trailer_heading_deg',-phi)
    hw=rig.get('trailer_half_width',0.85) or 0.85
    be=math.radians(th+180.0);ex=math.cos(be);ey=math.sin(be)
    pts=[]
    for k,(wx,wy,tt) in MEM.items():
        x,y=to_veh(wx,wy)
        dx=x-R[0];dy=y-R[1]
        u=dx*ex+dy*ey;w=-dx*ey+dy*ex
        if u>-3.5 and u<12: pts.append((u,w))
    best=None;bestfree=0;frees={}
    for a in range(-60,61,3):
        ca=math.cos(math.radians(a));sa=math.sin(math.radians(a))
        free=10.0
        for (u,w) in pts:
            pr=u*ca+w*sa
            if pr>0 and pr<free:
                if abs(-u*sa+w*ca)<hw+0.35: free=pr
        frees[a]=free
        sc=free-0.03*abs(a)-0.01*abs(a-last_alpha)
        if best is None or sc>best[0]: best=(sc,a);bestfree=free
    alpha=best[1] if best else 0.0
    lc=9;rc=9
    for (u,w) in pts:
        if -3.0<u<0.5:
            if w>0: lc=min(lc,w-hw)
            else: rc=min(rc,-w-hw)
    bias=0.0
    if lc<0.55: bias-=(0.55-lc)*30
    if rc<0.55: bias+=(0.55-rc)*30
    tg=obs.get('target',{}) or {}
    near=False;cap=16.0
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        eye=rig.get('eye',[1.62,0.41]);b=math.radians(tg.get('bearing_deg',180));d=tg['dist_m']
        tx=eye[0]+d*math.cos(b)-R[0];ty=eye[1]+d*math.sin(b)-R[1]
        tu=tx*ex+ty*ey;tw=-tx*ey+ty*ex
        dr=math.hypot(tu,tw)
        at=math.degrees(math.atan2(tw,tu))
        ak=int(clip(round(at/3)*3,-60,60))
        if tu>0 and frees.get(ak,0)>=dr-0.8:
            alpha=clip(at,-20,20)
        if dr<6: near=True;cap=9.0
    last_alpha=alpha
    phid=clip(-0.7*(alpha+bias),-cap,cap)
    steer=clip(deq(phi)+2.0*(phi-phid),-34,34)
    sp=-1.4
    if bestfree<3.0 or abs(phi)>12: sp=-0.9
    if near: sp=-0.6
    return (steer,sp,gaze_sched(t))

