import math
X=0.0;Y=0.0;PSI=0.0
pts={}
phase='rev'
fwd_d=0.0
touches=0
phi_f=0.0
gaze_t=0.0
side=1
bay=None
lastp=-10.0

def clamp(a,lo,hi):
    return max(lo,min(hi,a))

def wrap(a):
    while a>math.pi: a-=2*math.pi
    while a<-math.pi: a+=2*math.pi
    return a

def freelen(near,rx,ry,a):
    dx=math.cos(a);dy=math.sin(a);free=12.0
    for (px,py) in near:
        qx=px-rx;qy=py-ry
        al=qx*dx+qy*dy
        if al>0.3 and al<free:
            if abs(qx*dy-qy*dx)<1.5:
                free=al
    return free

def control(obs):
    global X,Y,PSI,phase,fwd_d,touches,phi_f,gaze_t,side,bay,lastp
    dt=obs.get('dt',0.1) or 0.1
    t=obs.get('t',0.0)
    m=obs['motion'];v=m['v_mps'];st=math.radians(obs['steer_deg'])
    PSI+=v*math.tan(st)/2.5*dt
    X+=v*math.cos(PSI)*dt;Y+=v*math.sin(PSI)*dt
    c=math.cos(PSI);s=math.sin(PSI)
    def tow(px,py):
        return (X+c*px-s*py,Y+s*px+c*py)
    views=obs.get('views') or {}
    for name in views:
        vw=views[name]
        if not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]):
            b,d=w[0],w[1]
            if d>14: continue
            br=math.radians(b)
            wx,wy=tow(ox+d*math.cos(br),oy+d*math.sin(br))
            pts[(round(wx/0.25),round(wy/0.25))]=(wx,wy)
    rig=obs['rig']
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        ex,ey=rig['eye'];br=math.radians(tg['bearing_deg']);d=tg['dist_m']
        bx,by=tow(ex+d*math.cos(br),ey+d*math.sin(br))
        if bay is None: bay=(bx,by)
        else: bay=(bay[0]*0.8+bx*0.2,bay[1]*0.8+by*0.2)
    h=obs['hitch_deg']
    tc=obs['counters']['touches']
    if tc>touches:
        touches=tc
        phase='fwd';fwd_d=0.0
        wake('touch %d, pulling forward'%tc)
    if obs.get('status')=='JACKKNIFED' or abs(h)>45:
        if phase!='fwd':
            phase='fwd';fwd_d=0.0
    if t-gaze_t>1.2:
        gaze_t=t;side=-side
    look=64*side
    if phase=='fwd':
        fwd_d+=abs(v)*dt
        steer=clamp(-1.5*h,-40,40)
        if fwd_d>2.0 and abs(h)<6:
            phase='rev'
        return (steer,1.0,look)
    rx,ry=tow(*rig['trailer_rear'])
    pt=PSI+math.radians(rig['trailer_heading_deg'])
    near=[p for p in pts.values() if (p[0]-rx)**2+(p[1]-ry)**2<225]
    phis=list(range(-70,71,5))
    frees=[freelen(near,rx,ry,pt+math.pi+math.radians(ph)) for ph in phis]
    mx=max(frees)
    thr=11.0 if mx>=12 else mx-1.0
    runs=[];cur=[]
    for i,f in enumerate(frees):
        if f>=thr: cur.append(phis[i])
        else:
            if cur: runs.append(cur)
            cur=[]
    if cur: runs.append(cur)
    runs.sort(key=lambda r:(-len(r),abs(r[len(r)//2])))
    r=runs[0]
    phi=(r[0]+r[-1])/2.0
    phi_f+=0.3*(phi-phi_f)
    phit=phi_f
    if bay is not None:
        dxb=bay[0]-rx;dyb=bay[1]-ry;db=math.hypot(dxb,dyb)
        if db<14:
            ang=wrap(math.atan2(dyb,dxb)-(pt+math.pi))
            if freelen(near,rx,ry,pt+math.pi+ang)>=db-1.5:
                phit=math.degrees(ang)
    hd=clamp(-1.1*phit,-30,30)
    hr=math.radians(hd)
    ff=math.degrees(math.atan(2.5*math.sin(hr)/(3.6+1.3*math.cos(hr))))
    steer=clamp(ff+2.5*(h-hd),-45,45)
    sp=-0.8 if mx>=3 else -0.5
    if t-lastp>2.0:
