                    ox,oy=vw['origin']
                    ps=[]
                    for w in vw.get('walls',[]):
                        b,d=w[0],w[1]
                        if d>15: continue
                        br=math.radians(b)
                        ps.append('%.1f,%.1f'%(ox+d*math.cos(br),oy+d*math.sin(br)))
                    cs=[]
                    for w in vw.get('target_corners',[]) or []:
                        try:
                            b,d=w[0],w[1];br=math.radians(b)
                            cs.append('%.1f,%.1f'%(ox+d*math.cos(br),oy+d*math.sin(br)))
                        except Exception: pass
                    if ps or cs:
                        rec.append('g%d %s: %s%s'%(g,name[:2],' '.join(ps),(' BAY '+' '.join(cs)) if cs else ''))
