        print('HOLD '+msg)
        wake('hold: '+msg)
    return (obs['steer_deg'],0.0,look)

def control(obs):
    global X,Y,PSI,phase,fd,gi,gt,bay,lastp,woke,stuck,mode,cf,hdf
    dt=obs.get('dt',0.1) or 0.1
    t=obs.get('t',0.0)
    m=obs['motion'];v=m['v_mps'];stv=obs['steer_deg']
    PSI+=v*math.tan(math.radians(stv))/2.5*dt
    X+=v*math.cos(PSI)*dt;Y+=v*math.sin(PSI)*dt
    c=math.cos(PSI);s=math.sin(PSI)
    vws=obs.get('views') or {}
    for nm in vws:
        vw=vws[nm]
        if not vw: continue
        lim=6.0 if nm=='right_mirror' else 14.0
        ox,oy=vw['origin']
        for w in vw.get('walls',[]) or []:
            b,d=w[0],w[1]
            if d>lim: continue
            br=math.radians(b)
            px=ox+d*math.cos(br);py=oy+d*math.sin(br)
            wx=X+c*px-s*py;wy=Y+s*px+c*py
            pts[(round(wx/0.25),round(wy/0.25))]=(wx,wy,t)
    rec=[(p[0],p[1]) for p in pts.values() if (p[2]<0 or t-p[2]<4.0) and (p[0]-X)**2+(p[1]-Y)**2<200]
    rig=obs['rig']
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        ex,ey=rig['eye'];br=math.radians(tg['bearing_deg']);d=tg['dist_m']
        px=ex+d*math.cos(br);py=ey+d*math.sin(br)
        bx=X+c*px-s*py;by=Y+s*px+c*py
        bay=(bx,by) if bay is None else (bay[0]*0.85+bx*0.15,bay[1]*0.85+by*0.15)
    h=obs['hitch_deg'];hr=math.radians(h)
    vf=rig.get('vehicle_front',3.3)
    if isinstance(vf,(list,tuple)): vf=vf[0]
    vr=vf-3.9
    ux=math.cos(-hr);uy=math.sin(-hr)
    gfr=9.0;gfl=9.0;trr=9.0;trl=9.0;cmin=9.0;cfront=9.0
    for (x,y) in rec:
        dx=x-X;dy=y-Y
        vx=c*dx+s*dy;vy=-s*dx+c*dy
        ex_=max(vr-vx,vx-vf,0.0);ey_=max(abs(vy)-1.15,0.0)
        dv=math.hypot(ex_,ey_)
        cmin=min(cmin,dv)
        if vx>0.5: cfront=min(cfront,dv)
        if 0.8<vx<vf+0.3:
            if vy<0: gfr=min(gfr,-vy-1.15)
            else: gfl=min(gfl,vy-1.15)
        qx=vx+1.3;qy=vy
        al=qx*ux+qy*uy;la=ux*qy-uy*qx
        ex_=max(-5.0-al,al+0.4,0.0);ey_=max(abs(la)-1.2,0.0)
        cmin=min(cmin,math.hypot(ex_,ey_))
        if -5.1<al<-0.6:
            if la>0: trl=min(trl,la-1.2)
            else: trr=min(trr,-la-1.2)
    if t-gt>0.5:
        gt=t;gi=(gi+1)%4
    if phase=='hold':
        return (stv,0.0,GR[gi])
    if phase=='f':
        fd+=abs(v)*dt
        steer=-25.0
        if cfront<0.15 and fd>0.05: return hold('front close %.2f'%cfront,obs,GF[gi])
        if gfr<0.35: steer=0.0
        if math.degrees(PSI)<7.0 or fd>2.8:
            phase='rev';stuck=0.0
        if t-lastp>1.5:
            lastp=t
            print('F t%.1f pos(%.1f,%.1f,%.0f) h%.1f fd%.1f gfr%.2f gfl%.2f cf%.2f'%(t,X,Y,math.degrees(PSI),h,fd,gfr,gfl,cfront))
        return (steer,1.0,GF[gi])
    if obs.get('status')=='JACKKNIFED' or abs(h)>50:
        return hold('hitch %.1f'%h,obs,GR[gi])
    th=PSI-hr
    hx=X-1.3*c;hy=Y-1.3*s
    axx=hx-3.6*math.cos(th);axy=hy-3.6*math.sin(th)
    sa=proj(axx,axy)
    bux=-math.cos(th);buy=-math.sin(th)
    rx=axx-1.4*math.cos(th);ry=axy-1.4*math.sin(th)
    if sa>SEND-1.0 and not woke:
        woke=True
        seen=set();out=[]
        for p in pts.values():
            if p[2]>=0 and (p[0]<-6.0 or p[1]>7.0):
                k=(round(p[0]*2)/2.0,round(p[1]*2)/2.0)
                if k not in seen:
                    seen.add(k);out.append('%.1f,%.1f'%k)
        print('POS(%.1f,%.1f,%.0f) h%.1f th%.0f sa%.1f rear(%.1f,%.1f) bay%s'%(X,Y,math.degrees(PSI),h,math.degrees(th),sa,rx,ry,str(bay and (round(bay[0],1),round(bay[1],1)))))
        print('MAP '+' '.join(sorted(out)[:120]))
        wake('end of mapped bend')
    if mode=='path' and sa>SEND: mode='gap'
    if mode=='path':
        tx,ty=at(sa+4.0)
        qx=tx-axx;qy=ty-axy
        a=qx*bux+qy*buy;la=bux*qy-buy*qx
        alpha=math.degrees(math.atan2(la,max(a,1.0)))
        hd=cl(-1.4*alpha,-30,30)
    else:
        Lp=None;Rn=None
        for (x,y) in rec:
            qx=x-rx;qy=y-ry
            a=qx*bux+qy*buy;la=bux*qy-buy*qx
            if 1.0<a<7.0:
                if la>0.2: Lp=la if Lp is None else min(Lp,la)
                elif la<-0.2: Rn=la if Rn is None else max(Rn,la)
        if Lp is not None and Rn is not None: cen=(Lp+Rn)/2.0
        elif Lp is not None: cen=Lp-2.4
        elif Rn is not None: cen=Rn+2.4
        else: cen=0.0
        cen=cl(cen,-3,3)
        phi=math.degrees(math.atan2(cen,4.5))
        hlim=28.0
        if bay is not None:
            qx=bay[0]-rx;qy=bay[1]-ry
            ab=qx*bux+qy*buy;lb=bux*qy-buy*qx
            if -1.0<ab<14.0:
                phi=math.degrees(math.atan2(lb,max(ab,3.0)))
                hlim=cl(6+2.5*ab,6,28)
        cf+=0.35*(phi-cf)
        hd=cl(-1.3*cf,-hlim,hlim)
    if trr<0.5: hd+=30*(0.5-trr)
    if trl<0.5: hd-=30*(0.5-trl)
    hd=cl(hd,-35,35)
    if hdf is None: hdf=h
    hdf+=cl(hd-hdf,-1.5,1.5)
    hdr=math.radians(hdf)
    ff=math.degrees(math.atan(2.5*math.sin(hdr)/(3.6+1.3*math.cos(hdr))))
    steer=cl(ff+2.2*(h-hdf),-45,45)
    if cmin<0.15:
        return hold('clear %.2f gfr%.2f gfl%.2f trr%.2f trl%.2f pos(%.1f,%.1f,%.0f) h%.1f'%(cmin,gfr,gfl,trr,trl,X,Y,math.degrees(PSI),h),obs,GR[gi])
    sp=-0.65 if cmin>0.6 else -0.35
    if (m.get('hold_s') or 0)<=0 and abs(v)<0.03: stuck+=dt
    else: stuck=0.0
    if stuck>3.0:
        return hold('stuck',obs,GR[gi])
    if t-lastp>2.0:
        lastp=t
        print('R t%.1f pos(%.1f,%.1f,%.0f) sa%.1f %s h%.1f hd%.1f cmin%.2f gfr%.2f gfl%.2f trr%.2f trl%.2f st%.0f rear(%.1f,%.1f)'%(t,X,Y,math.degrees(PSI),sa,mode,h,hdf,cmin,gfr,gfl,trr,trl,steer,rx,ry))
    return (steer,sp,GR[gi])

