import math
L=1.25;A=0.3;B=0.85
X=0.0;Y=0.0;PSI=0.0
UA=math.radians(-115);UB=(math.cos(UA),math.sin(UA))
GX=0.1+7.5*math.cos(math.radians(-131));GY=7.5*math.sin(math.radians(-131))
W={}
mode='rev';fwd_s=0.0;touch0=None
LOOKS=[-100,60,150];li=0;dw=0;cyc=0
lastp=-10.0;prev=None;nf=0;cnt=0;last=(0.0,0.0)
def cl(x,a,b): return max(a,min(b,x))
def wrap(a): return (a+math.pi)%(2*math.pi)-math.pi
def eqst(hr): return math.degrees(math.atan(L*math.sin(hr)/(B+A*math.cos(hr))))
def rects(x,y,psi,h):
    c=math.cos(psi);s=math.sin(psi)
    m=(x+0.6*c,y+0.6*s,c,s,0.9,0.525)
    pt=psi-h;ct=math.cos(pt);st=math.sin(pt)
    ax=x-A*c-B*ct;ay=y-A*s-B*st
    t=(ax+0.05*ct,ay+0.05*st,ct,st,0.5,0.475)
    return (m,t),(ax-0.45*ct,ay-0.45*st),pt
def clear(rs,pts):
    best=9.0
    for (cx,cy,c,s,hl,hw) in rs:
        for (px,py) in pts:
            dx=px-cx;dy=py-cy
            lx=abs(dx*c+dy*s)-hl;ly=abs(dy*c-dx*s)-hw
            if lx<0: lx=0.0
            if ly<0: ly=0.0
            dd=(lx*lx+ly*ly)**0.5
            if dd<best: best=dd
    return best
def sim(x,y,psi,h,d,v,hr,stf,dist,pts,c0):
    ds=0.05;n=int(dist/ds+0.5);sd=ds if v>0 else -ds
    rate=math.radians(48)*ds/max(abs(v),0.1)
    mc=9.0;ok=True
    for i in range(n):
        if hr is None: tg=math.radians(stf)
        else: tg=math.radians(cl(eqst(hr)+2.0*math.degrees(h-hr),-45,45))
        d+=cl(tg-d,-rate,rate)
        w=sd*math.tan(d)/L
        h+=w-sd*math.sin(h)/B+A*w*math.cos(h)/B
        x+=sd*math.cos(psi);y+=sd*math.sin(psi);psi+=w
        if i%3==2 or i==n-1:
            rs,P,pt=rects(x,y,psi,h)
            cc=clear(rs,pts)
            if cc<mc: mc=cc
            if cc<min(0.06,c0-0.02):
                ok=False;break
        if abs(h)>math.radians(60):
            ok=False;break
    rs,P,pt=rects(x,y,psi,h)
    return ok,mc,P,pt,h
def rcost(P,pt,h,mc):
    dx=GX-P[0];dy=GY-P[1];dist=math.hypot(dx,dy)
    e=UB[0]*(P[1]-GY)-UB[1]*(P[0]-GX)
    rd=pt+math.pi
    d1=math.atan2(dy,dx)
    d2=UA-cl(0.8*e,-0.6,0.6)
    w=cl((dist-1.0)/3.0,0,1)
    des=d2+w*wrap(d1-d2)
    return abs(wrap(rd-des))+0.3*abs(e)*(1-w)+0.3*abs(h)+0.6*max(0,0.3-mc)/0.3+0.1*dist
def control(obs):
    global X,Y,PSI,GX,GY,mode,fwd_s,touch0,li,dw,cyc,lastp,prev,nf,cnt,last
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];d=math.radians(obs['steer_deg'])
    X+=v*math.cos(PSI)*dt;Y+=v*math.sin(PSI)*dt;PSI+=v/L*math.tan(d)*dt
    c=math.cos(PSI);s=math.sin(PSI)
    h=math.radians(obs['hitch_deg'])
    t=obs['t']
    for k,vw in (obs.get('views') or {}).items():
        ox,oy=vw['origin']
        for b,dd in (vw.get('walls') or []):
            if dd>6.5: continue
            br=math.radians(b)
            px=ox+dd*math.cos(br);py=oy+dd*math.sin(br)
            wx=X+px*c-py*s;wy=Y+px*s+py*c
            W[(int(round(wx/0.1)),int(round(wy/0.1)))]=(wx,wy)
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') and tg.get('bearing_deg') is not None and tg['dist_m']>2.0:
        dd=tg['dist_m'];br=math.radians(tg['bearing_deg'])
        px=0.1+dd*math.cos(br);py=dd*math.sin(br)
        GX+=0.04*(X+px*c-py*s-GX);GY+=0.04*(Y+px*s+py*c-GY)
    hd=obs['head']
    if abs(hd['gaze_deg']-LOOKS[li])<3 and hd.get('settled'):
        dw+=1
        if dw>=2:
            dw=0;li=(li+1)%3
            if li==0: cyc+=1
    look=LOOKS[li]
    tc=obs['counters']['touches']
    if touch0 is None: touch0=tc
    if tc>touch0:
        touch0=tc
        if mode=='rev':
            mode='fwd';fwd_s=0.0
        else:
            mode='rev'
    if obs['motion']['hold_s']>0 or cyc<1:
        return (obs['steer_deg'],0,look)
    hx=X-A*c;hy=Y-A*s
    pts=[p for p in W.values() if abs(p[0]-hx)<3.4 and abs(p[1]-hy)<3.4]
    rs,P,pt=rects(X,Y,PSI,h)
    c0=clear(rs,pts)
    a=(P[0]-GX)*UB[0]+(P[1]-GY)*UB[1]
    if t-lastp>=2.0:
        lastp=t
        print('t%.1f %s P(%.2f,%.2f) G(%.2f,%.2f) a%.2f psi%.0f pt%.0f h%.0f c0%.2f n%d prev%s'%(t,mode,P[0],P[1],GX,GY,a,math.degrees(PSI),math.degrees(pt),math.degrees(h),c0,len(pts),prev))
    if a>0.5:
        return (obs['steer_deg'],0,look)
    cnt+=1
    if mode=='rev' and abs(h)>math.radians(50):
        mode='fwd';fwd_s=0.0
    if mode=='rev':
        if cnt%2==0 or prev is None:
            best=None
            for hrd in range(-48,49,12):
                ok,mc,P2,pt2,h2=sim(X,Y,PSI,h,d,-0.25,math.radians(hrd),0,1.2,pts,c0)
                if not ok: continue
                co=rcost(P2,pt2,h2,mc)
                if prev is not None and hrd==prev: co-=0.05
                if best is None or co<best[0]: best=(co,hrd)
            if best is None:
                nf+=1
                if nf>=3:
                    mode='fwd';fwd_s=0.0;nf=0
                return (obs['steer_deg'],0,look)
            nf=0;prev=best[1]
        hr=math.radians(prev)
        st=cl(eqst(hr)+2.0*math.degrees(h-hr),-45,45)
        return (st,-0.25,look)
    fwd_s+=abs(v)*dt
    if cnt%2==0 or last[1]<=0:
        best=None
        for sd in range(-45,46,15):
            ok,mc,P2,pt2,h2=sim(X,Y,PSI,h,d,0.3,None,sd,0.6,pts,c0)
            co=0.5*abs(h2)-min(mc,0.6)+(5 if not ok else 0)
            if best is None or co<best[0]: best=(co,sd)
        last=(best[1],0.3)
    if fwd_s>0.5:
        anyok=fwd_s>1.5
        if not anyok:
            for hrd in range(-48,49,24):
                ok,mc,P2,pt2,h2=sim(X,Y,PSI,h,d,-0.25,math.radians(hrd),0,1.0,pts,c0)
                if ok:
                    anyok=True;break
        if anyok and abs(h)<math.radians(30):
            mode='rev';prev=None
    return (last[0],0.3,look)

