import math
L=1.25
X=0.0;Y=0.0;PSI=0.0
STEPS=[(-40,0.3,0.45)]
si=0;sd=0.0;done=False;t0=None;touch0=None;woke=False;lastp=-10
def control(obs):
    global X,Y,PSI,si,sd,done,t0,touch0,woke,lastp
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];d=math.radians(obs['steer_deg'])
    X+=v*math.cos(PSI)*dt;Y+=v*math.sin(PSI)*dt;PSI+=v/L*math.tan(d)*dt
    t=obs['t']
    if t0 is None: t0=t
    look=150 if int((t-t0)/1.5)%2==0 else -110
    tc=obs['counters']['touches']
    if touch0 is None: touch0=tc
    if tc>touch0 and not woke:
        woke=True;done=True;wake('touched')
    if t-lastp>=1.5:
        lastp=t
        pts=[]
        for k,vw in (obs.get('views') or {}).items():
            ox,oy=vw['origin']
            for b,dd in (vw.get('walls') or []):
                if dd>4.5: continue
                br=math.radians(b)
                pts.append('(%.1f,%.1f)'%(ox+dd*math.cos(br),oy+dd*math.sin(br)))
        print('t%.1f step%d X%.2f Y%.2f psi%.0f h%.0f pts:%s'%(t,si,X,Y,math.degrees(PSI),obs['hitch_deg'],' '.join(pts)))
    if done or si>=len(STEPS):
        if not done:
            done=True
        if not woke and obs['motion']['v_mps']==0:
            woke=True;wake('steps done')
        return (obs['steer_deg'],0,look)
    st,sp,ds=STEPS[si]
    if obs['motion']['hold_s']>0:
        return (st,0,look)
    if abs(obs['steer_deg']-st)>5 and abs(v)<0.05:
        return (st,0,look)
    sd+=abs(v)*dt
    if sd>=ds:
        si+=1;sd=0.0
        return (st,0,look)
    return (st,sp,look)

