    if s>0 and dr<0.35: s=min(s,42*max(0.0,(dr-0.1)/0.25))
    sp=-0.7
    if abs(hitch-pd)>25: sp=-0.5
    if cnt%10==0: print('R t%.1f h%.1f P%.1f pt%.1f TY%.1f yg%.1f ptg%.1f pd%.1f s%.1f dl%.2f dr%.2f'%(obs['t'],hitch,P,pt,TY,yg,ptg,pd,s,dl,dr))
    last=(s,sp,-41)
    return last
